import { useState, FC } from 'react';

// Define prop types
interface CourseCardProps {
  title: string;
  chapters: number;
  level: 'beginner' | 'intermediate' | 'advanced';
  onEnroll?: () => void; // Optional prop
}

// Typed function component
const CourseCard: FC<CourseCardProps> = ({ title, chapters, level, onEnroll }) => {
  return (
    <div>
      <h3>{title}</h3>
      <p>{chapters} chapters - {level}</p>
      {onEnroll && <button onClick={onEnroll}>Enroll</button>}
    </div>
  );
};

// Typed state
interface User {
  id: number;
  name: string;
  email: string;
}

function UserProfile() {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  return <div>{user ? user.name : 'No user loaded'}</div>;
}
